def _strict_int(value: object, name: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"worker {name} result was not an integer")
    return value


def _memory_arguments(arguments: dict[str, Any], *, write: bool) -> tuple[int, int]:
    width_bits = arguments.get("width_bits")
    if not isinstance(width_bits, int) or isinstance(width_bits, bool) or width_bits not in {8, 16, 32}:
        raise ValueError("worker memory width was invalid")
    address = arguments.get("address")
    if not isinstance(address, int) or isinstance(address, bool) or address < 0:
        raise ValueError("worker memory address was invalid")
    if write:
        value = arguments.get("value")
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 0
            or value > (1 << width_bits) - 1
        ):
            raise ValueError("worker memory write value was invalid for its width")
    return address, width_bits


def _validate_result(operation: str, value: object, arguments: dict[str, Any] | None = None) -> Any:
    void_operations = {
        "close",
        "write_memory",
        "write_core_register",
        "halt",
        "resume",
        "step",
        "reset",
        "reset_and_halt",
        "flash",
        "recover",
        "set_breakpoint",
        "remove_breakpoint",
        "release_reset",
    }
    if operation in void_operations:
        if value is not None:
            raise ValueError("worker void operation returned data")
        return None
    if operation == "get_state":
        if not isinstance(value, str) or not value:
            raise ValueError("worker state result was invalid")
        return value
    if operation == "read_memory":
        if arguments is None:
            raise ValueError("worker memory result lacked request facts")
        _, width_bits = _memory_arguments(arguments, write=False)
        result = _strict_int(value, operation)
        if result < 0 or result > (1 << width_bits) - 1:
            raise ValueError("worker memory result exceeded its requested width")
        return result
    if operation == "read_core_register":
        return _strict_int(value, operation)
    if operation == "read_memory_block":
        if arguments is None:
            raise ValueError("worker memory block result lacked request facts")
        length = arguments.get("length")
        if not isinstance(length, int) or isinstance(length, bool) or length < 1:
            raise ValueError("worker memory block request length was invalid")
        if not isinstance(value, list) or len(value) != length:
            raise ValueError("worker memory block length did not match the request")
        result = [_strict_int(item, "memory block item") for item in value]
        if any(item < 0 or item > 255 for item in result):
            raise ValueError("worker memory block item exceeded byte range")
        return result
    if operation == "supported_core_registers":
        if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
            raise ValueError("worker register-list result was invalid")
        return value
    if operation == "supports_recovery":
        if not isinstance(value, bool):
            raise ValueError("worker recovery capability result was invalid")
        return value
    if operation in {"open", "connect_under_reset"}:
        required = {
            "board_name",
            "probe_description",
            "probe_family",
            "probe_uid",
            "live_part_number",
            "route_used",
            "target_override",
            "runtime_token",
        }
        if not isinstance(value, dict) or set(value) != required:
            raise ValueError("worker session metadata schema was invalid")
        for key in {"board_name", "probe_description", "probe_family"}:
            if not isinstance(value[key], str):
                raise ValueError(f"worker metadata field {key} was invalid")
        for key in {"route_used", "runtime_token"}:
            if not isinstance(value[key], str) or not value[key]:
                raise ValueError(f"worker metadata field {key} was invalid")
        for key in {"probe_uid", "live_part_number", "target_override"}:
            if value[key] is not None and not isinstance(value[key], str):
                raise ValueError(f"worker metadata field {key} was invalid")
        return value
    raise ValueError("worker returned an unallowlisted operation")


def _positive_timeout(value: object, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, int | float):
        raise ValueError(f"{name} must be a finite positive number")
    numeric = float(value)
    if not math.isfinite(numeric) or numeric <= 0:
        raise ValueError(f"{name} must be a finite positive number")
    return numeric


def _timeout(timeout: float | None) -> float:
    return _positive_timeout(
        DEFAULT_EXTERNAL_COMMAND_TIMEOUT_SECONDS if timeout is None else timeout,
        "operation timeout",
    )


def _operation_deadline(operation_timeout_seconds: float | None = None) -> float:
    """Return the absolute provider deadline for the current call."""

    now = time.monotonic()
    if operation_timeout_seconds is not None:
        return now + _positive_timeout(operation_timeout_seconds, "operation timeout")
    operation = current_operation()
    if operation is None:
        return now + DEFAULT_EXTERNAL_COMMAND_TIMEOUT_SECONDS
    deadline = (
        operation.started_at
        + operation.timeout_seconds
        - CANCELLATION_CLEANUP_GRACE_SECONDS
    )
    if not math.isfinite(deadline) or deadline <= now:
        raise TargetConnectionError(
            "The managed operation has no provider time remaining after reserving cleanup time."
        )
    return deadline


def _remaining(deadline: float) -> float:
    if isinstance(deadline, bool) or not isinstance(deadline, int | float):
        raise ValueError("worker deadline must be a finite number")
    numeric = float(deadline)
    if not math.isfinite(numeric):
        raise ValueError("worker deadline must be a finite number")
    remaining = numeric - time.monotonic()
    if remaining <= 0:
        raise TimeoutError("worker request deadline elapsed")
    return remaining


class _WorkerClient:
    """One serial, owned worker protocol connection."""

    def __init__(
        self,
        *,
        worker_argv: Sequence[str] | None = None,
        deadline: float | None = None,
    ) -> None:
        self._guard = threading.RLock()
        self._request_id = 0
        self._closed = False
        self._cleanup_confirmed = False
        self._responses: queue.Queue[object] = queue.Queue()
        startup_deadline = deadline if deadline is not None else _operation_deadline()
        argv = tuple(worker_argv or (sys.executable, "-m", "pyocd_debug_mcp.adapters.provider_worker"))
        self._process, self._marker = popen_owned(
            argv,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=None,
            bufsize=0,
        )
        try:
            self._start_reader(self._process.stdout, self._responses)
            ready = self._read(startup_deadline)
            if not isinstance(ready, dict) or ready != {"version": _VERSION, "ready": True}:
                raise ValueError("worker did not provide the required ready handshake")
        except BaseException as exc:
            self._invalidate(f"Worker startup failed: {type(exc).__name__}: {exc}.")

    @staticmethod
    def _start_reader(stream: Any, responses: queue.Queue[object]) -> None:
        def read() -> None:
            try:
                pending = bytearray()
                while True:
                    chunk = stream.read(4096)
                    if not chunk:
                        responses.put(EOFError("worker protocol stream closed"))
                        return
                    pending.extend(chunk)
                    while b"\n" in pending:
                        raw_frame, _, remainder = pending.partition(b"\n")
                        pending = bytearray(remainder)
                        try:
                            responses.put(json.loads(raw_frame.decode("utf-8")))
                        except (UnicodeError, json.JSONDecodeError) as exc:
                            responses.put(ValueError(f"invalid worker frame: {exc}"))
                            return
            except BaseException as exc:  # reader must wake a bounded parent request
                responses.put(exc)

        threading.Thread(target=read, daemon=True).start()

    def _close_pipes(self) -> None:
        for stream in (self._process.stdin, self._process.stdout):
            if stream is not None:
                try:
                    stream.close()
                except (OSError, ValueError):
                    pass

    def _terminate(self) -> bool:
        try:
            cleaned = terminate_process_group(self._process)
        except Exception:
            return False
        finally:
            self._close_pipes()
        if cleaned:
            try:
                self._process.poll()
            except OSError:
                pass
        return cleaned

    def _remove_confirmed_marker(self, context: str) -> None:
        """Remove a dead worker's marker or report typed, retryable cleanup."""

        marker = self._marker
        if marker is None:
            return
        try:
            ProcessMarkerStore.remove(marker)
        except OSError as exc:
            raise TargetConnectionError(
                f"{context} Recovery marker removal failed: "
                f"{type(exc).__name__}: {exc}. The marker remains retained and close may retry it."
            ) from exc
        self._marker = None

    def _read(self, deadline: float) -> object:
        try:
            item = self._responses.get(timeout=_remaining(deadline))
        except queue.Empty as exc:
            raise TimeoutError("worker did not reply before the deadline") from exc
        if isinstance(item, BaseException):
            raise item
        return item

    def _write(self, frame: bytes, deadline: float) -> None:
        stdin = self._process.stdin
        if stdin is None:
            raise EOFError("worker stdin is unavailable")
        completed = threading.Event()
        failure: list[BaseException] = []

        def write() -> None:
            try:
                stdin.write(frame)
                stdin.flush()
            except BaseException as exc:
                failure.append(exc)
            finally:
                completed.set()

        threading.Thread(target=write, daemon=True).start()
        if not completed.wait(_remaining(deadline)):
            raise TimeoutError("worker pipe write exceeded the deadline")
        if failure:
            raise failure[0]

    def _invalidate(self, reason: str) -> NoReturn:
        if self._closed:
            suffix = (
                " Recovery marker remains retained."
                if not self._cleanup_confirmed or self._marker is not None
                else ""
            )
            raise TargetConnectionError(f"{reason}{suffix}")
        self._closed = True
        self._cleanup_confirmed = self._terminate()
        if self._cleanup_confirmed:
            self._remove_confirmed_marker(f"{reason} Worker was terminated.")
            raise TargetConnectionError(f"{reason} Worker was terminated.")
        raise TargetConnectionError(
            f"{reason} Worker termination could not be confirmed; recovery marker retained."
        )

    def call(
        self,
        operation: str,
        arguments: dict[str, Any],
        *,
        deadline: float | None = None,
        timeout: float | None = None,
    ) -> Any:
        if deadline is not None and timeout is not None:
            raise ValueError("pass either deadline or timeout, not both")
        call_deadline = (
            deadline
            if deadline is not None
            else time.monotonic() + _timeout(timeout)
        )
        _remaining(call_deadline)
        with self._guard:
            if self._closed:
                raise TargetConnectionError("The worker session is no longer live; reconnect and validate.")
            self._request_id += 1
            request_id = self._request_id
            payload = {
                "version": _VERSION,
                "request_id": request_id,
                "operation": operation,
                "arguments": arguments,
            }
            if operation == "read_memory":
                _memory_arguments(arguments, write=False)
            elif operation == "write_memory":
                _memory_arguments(arguments, write=True)
            raw = (json.dumps(payload, separators=(",", ":"), allow_nan=False) + "\n").encode("utf-8")
            try:
                self._write(raw, call_deadline)
                reply = self._read(call_deadline)
            except BaseException as exc:
                self._invalidate(f"Worker {operation} failed: {type(exc).__name__}: {exc}.")
            if not isinstance(reply, dict) or reply.get("version") != _VERSION:
                self._invalidate("Worker returned a malformed protocol reply.")
            if reply.get("request_id") != request_id:
                self._invalidate("Worker returned a stale or mismatched protocol reply.")
            if reply.get("ok") is True:
                if set(reply) != {"version", "request_id", "ok", "result"}:
                    self._invalidate("Worker returned an invalid success envelope.")
                try:
                    return _validate_result(operation, reply.get("result"), arguments)
                except ValueError as exc:
                    self._invalidate(f"Worker returned an invalid {operation} result: {exc}.")
            if reply.get("ok") is not False or set(reply) != {"version", "request_id", "ok", "error"}:
                self._invalidate("Worker returned an invalid error envelope.")
            error = reply.get("error")
            if not isinstance(error, dict) or set(error) != {"kind", "message"}:
                self._invalidate("Worker returned an invalid typed error envelope.")
            kind = error.get("kind")
            if kind not in {*_ERROR_TYPES, "provider_failure"}:
                self._invalidate("Worker returned an unallowlisted error kind.")
            message = error.get("message")
            if not isinstance(message, str):
                self._invalidate("Worker returned an invalid error message.")
            if kind == "provider_failure":
                raise TargetConnectionError(f"Worker {operation} failed: {kind}: {message}")
            error_type = _ERROR_TYPES.get(cast(str, kind))
            if error_type is None:
                self._invalidate("Worker returned an unallowlisted error kind.")
            raise error_type(f"Worker {operation} failed: {message}")

    def close(self, *, deadline: float | None = None) -> None:
        with self._guard:
            if self._closed:
                if self._cleanup_confirmed:
                    self._remove_confirmed_marker("Worker process cleanup was confirmed.")
                    return
                raise TargetConnectionError(
                    "Worker cleanup could not be confirmed; recovery marker retained."
                )
            try:
                try:
                    close_deadline = deadline if deadline is not None else _operation_deadline()
                    if close_deadline > time.monotonic():
                        self.call("close", {}, deadline=close_deadline)
                except Exception:
                    # Process termination is the ownership authority. Graceful-close
                    # failures, including a deadline race, are only diagnostics.
                    pass
            finally:
                if not self._closed:
                    self._closed = True
                    self._cleanup_confirmed = self._terminate()
                    if self._cleanup_confirmed:
                        self._remove_confirmed_marker("Worker process cleanup was confirmed.")
            if self._cleanup_confirmed:
                return
            raise TargetConnectionError(
                "Worker cleanup could not be confirmed; recovery marker retained."
            )


def _board_record(board: BoardConfig | None) -> dict[str, Any] | None:
    if board is None:
        return None
    record = asdict(board)
    record["source_path"] = str(board.source_path) if board.source_path is not None else None
    return record


class ProcessIsolatedSWDInterface(SWDInterface):
    """SWD proxy whose worker, not the MCP process, owns native providers."""

    def _open(
        self,
        operation: str,
        *,
        board: BoardConfig | None,
        unique_id: str | None,
        target: str | None,
        server_timeouts: ServerTimeoutConfig | None,
        protocol: str | None = None,
        connect_mode: str | None = None,
        pack_path: Path | None = None,
        pack_sha256: str | None = None,
        pdsc_device: str | None = None,
        frequency_hz: int | None = None,
        operation_timeout_seconds: float | None = None,
    ) -> TargetSessionHandle:
        deadline = _operation_deadline(operation_timeout_seconds)
        worker = _WorkerClient(deadline=deadline)
        arguments = {
            "board": _board_record(board),
            "unique_id": unique_id,
            "target": target,
            "server_timeouts": (server_timeouts or default_server_timeout_config()).to_record(),
            "protocol": protocol,
            "connect_mode": connect_mode,
            "pack_path": str(pack_path) if pack_path is not None else None,
            "pack_sha256": pack_sha256,
            "pdsc_device": pdsc_device,
            "frequency_hz": frequency_hz,
        }
        try:
            raw_metadata = worker.call(operation, arguments, deadline=deadline)
            metadata = TargetSessionMetadata(**cast(dict[str, Any], raw_metadata))
            return TargetSessionHandle(
                session=None,
                board=board,
                probe_uid=metadata.probe_uid,
                route_used=metadata.route_used,
                target_override=metadata.target_override,
                worker=worker,
                metadata=metadata,
            )
        except BaseException as primary:
            try:
                worker.close(deadline=deadline)
            except BaseException as cleanup:
                raise primary from cleanup
            raise

    def open(
        self,
        *,
        board: BoardConfig | None,
        unique_id: str | None,
        target: str | None,
        server_timeouts: ServerTimeoutConfig | None = None,
        protocol: str | None = None,
        connect_mode: str | None = None,
        pack_path: Path | None = None,
        pack_sha256: str | None = None,
        pdsc_device: str | None = None,
        frequency_hz: int | None = None,
        operation_timeout_seconds: float | None = None,
    ) -> TargetSessionHandle:
        return self._open(
            "open",
            board=board,
            unique_id=unique_id,
            target=target,
            server_timeouts=server_timeouts,
            protocol=protocol,
            connect_mode=connect_mode,
            pack_path=pack_path,
            pack_sha256=pack_sha256,
            pdsc_device=pdsc_device,
            frequency_hz=frequency_hz,
            operation_timeout_seconds=operation_timeout_seconds,
        )

    def connect_under_reset(
        self,
        *,
        board: BoardConfig | None,
        unique_id: str | None,
        target: str | None,
        server_timeouts: ServerTimeoutConfig | None = None,
        pack_path: Path | None = None,
        pack_sha256: str | None = None,
        pdsc_device: str | None = None,
        operation_timeout_seconds: float | None = None,
    ) -> TargetSessionHandle:
        return self._open(
            "connect_under_reset",
            board=board,
            unique_id=unique_id,
            target=target,
            server_timeouts=server_timeouts,
            pack_path=pack_path,
            pack_sha256=pack_sha256,
            pdsc_device=pdsc_device,
            operation_timeout_seconds=operation_timeout_seconds,
        )

    @staticmethod
    def _worker(handle: TargetSessionHandle) -> _WorkerClient:
        if not isinstance(handle.worker, _WorkerClient):
            raise TargetConnectionError("Target session has no live process worker.")
        return handle.worker

    def _call(
        self,
        handle: TargetSessionHandle,
        operation: str,
        arguments: dict[str, Any] | None = None,
        *,
        operation_timeout_seconds: float | None = None,
    ) -> Any:
        return self._worker(handle).call(
            operation,
            arguments or {},
            deadline=_operation_deadline(operation_timeout_seconds),
        )

    def close(self, handle: TargetSessionHandle) -> None:
        try:
            deadline = _operation_deadline()
        except TargetConnectionError:
            deadline = time.monotonic()
        self._worker(handle).close(deadline=deadline)

    def get_state(self, handle: TargetSessionHandle) -> str:
        return cast(str, self._call(handle, "get_state"))

    def read_memory(
        self,
        handle: TargetSessionHandle,
        address: int,
        width_bits: int,
        *,
        operation_timeout_seconds: float | None = None,
    ) -> int:
        return cast(
            int,
            self._call(
                handle,
                "read_memory",
                {"address": address, "width_bits": width_bits},
                operation_timeout_seconds=operation_timeout_seconds,
            ),
        )

    def read_memory_block(self, handle: TargetSessionHandle, address: int, length: int) -> list[int]:
        return cast(
            list[int],
            self._call(handle, "read_memory_block", {"address": address, "length": length}),
        )

    def write_memory(
        self, handle: TargetSessionHandle, address: int, value: int, width_bits: int
    ) -> None:
        self._call(
            handle,
            "write_memory",
            {"address": address, "value": value, "width_bits": width_bits},
        )

    def read_core_register(self, handle: TargetSessionHandle, name: str) -> int:
        return cast(int, self._call(handle, "read_core_register", {"name": name}))

    def write_core_register(self, handle: TargetSessionHandle, name: str, value: int) -> None:
        self._call(handle, "write_core_register", {"name": name, "value": value})

    def supported_core_registers(self, handle: TargetSessionHandle) -> tuple[str, ...]:
        return tuple(self._call(handle, "supported_core_registers"))

    def halt(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "halt")

    def resume(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "resume")

    def step(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "step")

    def reset(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "reset")

    def reset_and_halt(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "reset_and_halt")

    def release_reset(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "release_reset")

    def flash(
        self,
        handle: TargetSessionHandle,
        firmware: Path,
        *,
        halt_after_reset: bool,
    ) -> None:
        self._call(
            handle,
            "flash",
            {"path": str(firmware), "halt_after_reset": halt_after_reset},
        )

    def recover(self, handle: TargetSessionHandle) -> None:
        self._call(handle, "recover")

    def supports_recovery(self, handle: TargetSessionHandle, mechanism: str) -> bool:
        return cast(
            bool,
            self._call(handle, "supports_recovery", {"mechanism": mechanism}),
        )

    def set_breakpoint(self, handle: TargetSessionHandle, address: int) -> None:
        self._call(handle, "set_breakpoint", {"address": address})

    def remove_breakpoint(self, handle: TargetSessionHandle, address: int) -> None:
        self._call(handle, "remove_breakpoint", {"address": address})

"""Child-only JSON RPC loop that owns one native pyOCD session."""

from __future__ import annotations

import json
import math
import sys
from dataclasses import fields
from pathlib import Path
from typing import Any, BinaryIO, cast

from pyocd_debug_mcp.adapters.swd_interface import TargetSessionHandle
from pyocd_debug_mcp.adapters.swd_pyocd import (
    PyOCDSWDInterface,
)
from pyocd_debug_mcp.board_config import BoardConfig
from pyocd_debug_mcp.probe_inventory import probe_family_from_pyocd_probe
from pyocd_debug_mcp.target_errors import (
    LockedTargetError,
    ProbeNotFoundError,
    ResetLineUnavailableError,
    TargetConnectionError,
    TargetControlError,
    TargetStateError,
    UnsupportedArtifactError,
)
from pyocd_debug_mcp.timeouts import ServerTimeoutConfig

_VERSION = 1
_BOARD_FIELDS = {field.name for field in fields(BoardConfig)}
_TIMEOUT_FIELDS = set(ServerTimeoutConfig().to_record())
_ERROR_KINDS: tuple[tuple[type[TargetControlError], str], ...] = (
    (LockedTargetError, "locked_target"),
    (ProbeNotFoundError, "probe_not_found"),
    (ResetLineUnavailableError, "reset_line_unavailable"),
    (TargetStateError, "target_state"),
    (UnsupportedArtifactError, "unsupported_artifact"),
    (TargetConnectionError, "target_connection"),
    (TargetControlError, "target_control"),
)


def _integer(value: object, name: str, *, minimum: int | None = None) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{name} must be an integer")
    if minimum is not None and value < minimum:
        raise ValueError(f"{name} is below its allowed range")
    return value


def _text(value: object, name: str, *, nullable: bool = False) -> str | None:
    if value is None and nullable:
        return None
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    return value


def _exact(arguments: dict[str, Any], expected: set[str]) -> None:
    if set(arguments) != expected:
        raise ValueError("worker operation has missing or unknown arguments")


def _validate_arguments(operation: str, arguments: dict[str, Any]) -> None:
    no_arguments = {"close", "get_state", "supported_core_registers", "halt", "resume", "step", "reset", "reset_and_halt", "recover", "release_reset"}
    if operation in no_arguments:
        _exact(arguments, set())
        return
    if operation in {"open", "connect_under_reset"}:
        expected = {"board", "unique_id", "target", "server_timeouts", "protocol", "connect_mode", "pack_path", "pack_sha256", "pdsc_device", "frequency_hz"}
        _exact(arguments, expected)
        if arguments["board"] is not None and not isinstance(arguments["board"], dict):
            raise ValueError("board must be an object or null")
        for name in ("unique_id", "target", "protocol", "connect_mode", "pack_path", "pack_sha256", "pdsc_device"):
            _text(arguments[name], name, nullable=True)
        if arguments["frequency_hz"] is not None:
            _integer(arguments["frequency_hz"], "frequency_hz", minimum=1)
        if not isinstance(arguments["server_timeouts"], dict):
            raise ValueError("server_timeouts must be an object")
        return
    if operation == "read_memory":
        _exact(arguments, {"address", "width_bits"})
        _integer(arguments["address"], "address", minimum=0)
        if _integer(arguments["width_bits"], "width_bits") not in {8, 16, 32}:
            raise ValueError("width_bits is unsupported")
        return
    if operation == "read_memory_block":
        _exact(arguments, {"address", "length"})
        _integer(arguments["address"], "address", minimum=0)
        _integer(arguments["length"], "length", minimum=1)
        return
    if operation == "write_memory":
        _exact(arguments, {"address", "value", "width_bits"})
        _integer(arguments["address"], "address", minimum=0)
        value = _integer(arguments["value"], "value", minimum=0)
        width_bits = _integer(arguments["width_bits"], "width_bits")
        if width_bits not in {8, 16, 32}:
            raise ValueError("width_bits is unsupported")
        if value > (1 << width_bits) - 1:
            raise ValueError("value exceeded requested memory width")
        return
    if operation in {"read_core_register", "supports_recovery"}:
        field = "name" if operation == "read_core_register" else "mechanism"
        _exact(arguments, {field})
        _text(arguments[field], field)
        return
    if operation == "write_core_register":
        _exact(arguments, {"name", "value"})
        _text(arguments["name"], "name")
        _integer(arguments["value"], "value", minimum=0)
        return
    if operation in {"set_breakpoint", "remove_breakpoint"}:
        _exact(arguments, {"address"})
        _integer(arguments["address"], "address", minimum=0)
        return
    if operation == "flash":
        _exact(arguments, {"path", "halt_after_reset"})
        _text(arguments["path"], "path")
        if not isinstance(arguments["halt_after_reset"], bool):
            raise ValueError("halt_after_reset must be boolean")
        return
    raise ValueError("unknown worker operation")


def _send(protocol: BinaryIO, payload: dict[str, Any]) -> None:
    encoded = (json.dumps(payload, separators=(",", ":"), allow_nan=False) + "\n").encode("utf-8")
    protocol.write(encoded)
    protocol.flush()


def _error_kind(error: Exception) -> str:
    for error_type, kind in _ERROR_KINDS:
        if isinstance(error, error_type):
            return kind
    return "provider_failure"


def _board(raw: object) -> BoardConfig | None:
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise ValueError("board must be an object or null")
    record = dict(raw)
    if set(record) != _BOARD_FIELDS:
        raise ValueError("board record has missing or unknown fields")
    required_text = {
        "board_id", "display_name", "mcu_family", "probe_family", "pyocd_target", "probe_type",
        "silicon_id_label", "uart_note",
    }
    nullable_text = {"recover_mode", "debug_protocol", "debug_connect_mode", "expected_uart_substring"}
    for key in required_text:
        _text(record[key], key)
    for key in nullable_text:
        _text(record[key], key, nullable=True)
    for key in {"test_addr", "silicon_id_addr", "silicon_id_expected", "silicon_id_mask", "debug_clock_hz"}:
        if record[key] is not None:
            _integer(record[key], key)
    for key in {"silicon_id_width_bits", "default_baudrate"}:
        _integer(record[key], key, minimum=0)
    for key in {"requires_recover_validation"}:
        if not isinstance(record[key], bool):
            raise ValueError(f"{key} must be boolean")
    for key in {"probe_hint_terms", "serial_hint_terms"}:
        value = record[key]
        if not isinstance(value, list):
            raise ValueError(f"{key} must be a string list")
        for item in value:
            _text(item, key)
    if record.get("source_path") is not None:
        record["source_path"] = Path(str(_text(record["source_path"], "source_path")))
    for key in ("probe_hint_terms", "serial_hint_terms"):
        if isinstance(record.get(key), list):
            record[key] = tuple(str(item) for item in record[key])
    return BoardConfig(**record)


def _timeouts(raw: object) -> ServerTimeoutConfig:
    if not isinstance(raw, dict):
        raise ValueError("server_timeouts must be an object")
    if set(raw) != _TIMEOUT_FIELDS:
        raise ValueError("server_timeouts has missing or unknown fields")
    values: dict[str, float] = {}
    for key, value in raw.items():
        if isinstance(value, bool) or not isinstance(value, int | float):
            raise ValueError(f"{key} must be a finite positive number")
        number = float(value)
        if not math.isfinite(number) or number <= 0:
            raise ValueError(f"{key} must be a finite positive number")
        values[key] = number
    return ServerTimeoutConfig(**values)


def _metadata(handle: TargetSessionHandle) -> dict[str, Any]:
    session = handle.session
    probe = getattr(session, "probe", None)
    board = getattr(session, "board", None)
    target = getattr(session, "target", None)
    probe_uid = handle.probe_uid or getattr(probe, "unique_id", None)
    part_number = getattr(target, "part_number", None)
    metadata = handle.metadata
    if metadata is None:  # TargetSessionHandle guarantees this, retain an honest failure.
        raise RuntimeError("native session did not provide runtime metadata")
    return {
        "probe_uid": str(probe_uid) if probe_uid else None,
        "route_used": str(handle.route_used),
        "target_override": handle.target_override,
        "board_name": str(getattr(board, "name", "") or metadata.board_name),
        "probe_description": str(getattr(probe, "description", "") or ""),
        "probe_family": probe_family_from_pyocd_probe(probe),
        "live_part_number": str(part_number) if part_number else None,
        "runtime_token": metadata.runtime_token,
    }


def _dispatch(adapter: PyOCDSWDInterface, handle: TargetSessionHandle | None, operation: str,
              arguments: dict[str, Any]) -> tuple[TargetSessionHandle | None, Any, bool]:
    if operation in {"open", "connect_under_reset"}:
        if handle is not None:
            raise RuntimeError("worker already has a live session")
        kwargs = {
            "board": _board(arguments.get("board")),
            "unique_id": arguments.get("unique_id"),
            "target": arguments.get("target"),
            "server_timeouts": _timeouts(arguments.get("server_timeouts")),
            "pack_path": Path(arguments["pack_path"]) if arguments.get("pack_path") else None,
            "pack_sha256": arguments.get("pack_sha256"),
            "pdsc_device": arguments.get("pdsc_device"),
        }
        if operation == "open":
            handle = adapter.open(
                **kwargs,
                protocol=arguments.get("protocol"),
                connect_mode=arguments.get("connect_mode"),
                frequency_hz=arguments.get("frequency_hz"),
            )
        else:
            handle = adapter.connect_under_reset(**kwargs)
        return handle, _metadata(handle), False
    if operation == "close":
        if handle is not None:
            adapter.close(handle)
        return None, None, True
    if handle is None:
        raise RuntimeError("worker has no live target session")
    if operation == "get_state":
        result = adapter.get_state(handle)
    elif operation == "read_memory":
        result = adapter.read_memory(handle, int(arguments["address"]), int(arguments["width_bits"]))
        width_bits = int(arguments["width_bits"])
        if not isinstance(result, int) or isinstance(result, bool) or not 0 <= result <= (1 << width_bits) - 1:
            raise RuntimeError("memory read result exceeded requested width")
    elif operation == "read_memory_block":
        requested_length = int(arguments["length"])
        result = adapter.read_memory_block(handle, int(arguments["address"]), requested_length)
        if len(result) != requested_length or any(
            not isinstance(value, int) or isinstance(value, bool) or not 0 <= value <= 255
            for value in result
        ):
            raise RuntimeError("memory block result did not exactly match the requested byte block")
    elif operation == "write_memory":
        width_bits = int(arguments["width_bits"])
        if int(arguments["value"]) > (1 << width_bits) - 1:
            raise ValueError("value exceeded requested memory width")
        result = adapter.write_memory(
            handle, int(arguments["address"]), int(arguments["value"]), int(arguments["width_bits"])
        )
    elif operation == "read_core_register":
        result = adapter.read_core_register(handle, str(arguments["name"]))
    elif operation == "write_core_register":
        result = adapter.write_core_register(handle, str(arguments["name"]), int(arguments["value"]))
    elif operation == "supported_core_registers":
        result = list(adapter.supported_core_registers(handle))
    elif operation == "halt":
        result = adapter.halt(handle)
    elif operation == "resume":
        result = adapter.resume(handle)
    elif operation == "step":
        result = adapter.step(handle)
    elif operation == "reset":
        result = adapter.reset(handle)
    elif operation == "reset_and_halt":
        result = adapter.reset_and_halt(handle)
    elif operation == "flash":
        result = adapter.flash(
            handle, Path(str(arguments["path"])), halt_after_reset=bool(arguments["halt_after_reset"])
        )
    elif operation == "recover":
        result = adapter.recover(handle)
    elif operation == "supports_recovery":
        result = adapter.supports_recovery(handle, str(arguments["mechanism"]))
    elif operation == "set_breakpoint":
        result = adapter.set_breakpoint(handle, int(arguments["address"]))
    elif operation == "remove_breakpoint":
        result = adapter.remove_breakpoint(handle, int(arguments["address"]))
    elif operation == "release_reset":
        result = adapter.release_reset(handle)
    else:
        raise ValueError(f"unknown worker operation: {operation}")
    return handle, result, False


def main(protocol: BinaryIO) -> None:
    adapter = PyOCDSWDInterface()
    handle: TargetSessionHandle | None = None
    last_request_id = 0
    _send(protocol, {"version": _VERSION, "ready": True})
    pending = bytearray()
    while True:
        chunk = cast(Any, sys.stdin.buffer).read1(4096)
        if not chunk:
            return
        pending.extend(chunk)
        while b"\n" in pending:
            raw, _, remainder = pending.partition(b"\n")
            pending = bytearray(remainder)
            request_id: object = None
            try:
                request = json.loads(raw.decode("utf-8"))
                if (
                    not isinstance(request, dict)
                    or set(request) != {"version", "request_id", "operation", "arguments"}
                    or request.get("version") != _VERSION
                ):
                    raise ValueError("unsupported worker protocol frame")
                request_id = request.get("request_id")
                operation = request.get("operation")
                arguments = request.get("arguments")
                if not isinstance(request_id, int) or isinstance(request_id, bool) or request_id < 1:
                    raise ValueError("invalid worker request id")
                if request_id != last_request_id + 1:
                    raise ValueError("worker request id was not the next monotonic id")
                if not isinstance(operation, str) or not isinstance(arguments, dict):
                    raise ValueError("invalid worker request schema")
                _validate_arguments(operation, arguments)
                last_request_id = request_id
                handle, result, exit_after = _dispatch(
                    adapter,
                    handle,
                    operation,
                    arguments,
                )
                _send(
                    protocol,
                    {"version": _VERSION, "request_id": request_id, "ok": True, "result": result},
                )
                if exit_after:
                    return
            except Exception as exc:  # parent maps all child failures to typed connection failure
                kind = _error_kind(exc)
                _send(
                    protocol,
                    {
                        "version": _VERSION,
                        "request_id": request_id,
                        "ok": False,
                        "error": {"kind": kind, "message": str(exc)},
                    }
                )

"""Shared board-config schema and loader for Phase A tools."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

from pyocd_debug_mcp.probe_families import probe_family_hints, probe_family_label

BOARD_CONFIG_SUFFIXES = frozenset({".json", ".yaml", ".yml"})  # PROJECT-DEFINED (supported formats)

# Typed recover-mode selector — board YAML names a backend, never a raw shell command.
# PROJECT-DEFINED (the recover policy vocabulary for board configs).
RECOVER_MODE_BACKEND_MASS_ERASE = "backend_mass_erase"
RECOVER_MODE_MANUAL_ONLY = "manual_only"
SUPPORTED_RECOVER_MODES = {
    RECOVER_MODE_BACKEND_MASS_ERASE,
    RECOVER_MODE_MANUAL_ONLY,
}
class ConfigError(Exception):
    """Raised when a tracked board-config file is malformed."""


@dataclass(frozen=True)
class BoardConfig:
    board_id: str
    display_name: str
    mcu_family: str
    probe_family: str
    pyocd_target: str
    probe_type: str
    probe_hint_terms: tuple[str, ...]
    serial_hint_terms: tuple[str, ...]
    test_addr: int | None
    silicon_id_addr: int | None = None
    silicon_id_expected: int | None = None
    silicon_id_mask: int | None = None
    silicon_id_width_bits: int = 32
    silicon_id_label: str = ""
    default_baudrate: int = 115200
    uart_note: str = ""
    requires_recover_validation: bool = False
    recover_mode: str | None = None
    debug_protocol: str | None = None
    debug_connect_mode: str | None = None
    debug_clock_hz: int | None = None
    expected_uart_substring: str | None = None
    source_path: Path | None = None


def normalize_list(value: object) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        if "," in value:
            return [item.strip() for item in value.split(",") if item.strip()]
        if value.strip():
            return [value.strip()]
        return []
    if isinstance(value, (list, tuple)):
        output = []
        for item in value:
            if item is None:
                continue
            text = str(item).strip()
            if text:
                output.append(text)
        return output
    raise ConfigError(f"Expected a string or list, got {type(value).__name__}")


def parse_int(value: object, field_name: str) -> int:
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        return int(value, 0)
    raise ConfigError(f"Field '{field_name}' must be an int or numeric string")


def validate_width_bits(width_bits: int, field_name: str) -> int:
    if width_bits not in {8, 16, 32}:
        raise ConfigError(f"Field '{field_name}' must be one of: 8, 16, 32")
    return width_bits


def resolve_recover_mode(
    raw_mode: object,
    *,
    requires_recover_validation: bool,
) -> str | None:
    """Resolve the typed recover-mode selector for a board.

    An explicit ``recover_mode`` is honored and validated against
    ``SUPPORTED_RECOVER_MODES``. Missing recovery policy never infers behavior
    from a part or family name.
    """
    if raw_mode is not None:
        recover_mode = str(raw_mode).strip().lower()
        if not recover_mode:
            return None
        if recover_mode not in SUPPORTED_RECOVER_MODES:
            supported = ", ".join(sorted(SUPPORTED_RECOVER_MODES))
            raise ConfigError(f"Field 'recover_mode' must be one of: {supported}")
        return recover_mode

    if not requires_recover_validation:
        return None
    return RECOVER_MODE_MANUAL_ONLY


def tokenize_hint_text(*values: str) -> set[str]:
    terms: set[str] = set()
    for value in values:
        for token in re.findall(r"[a-z0-9]+", value.lower()):
            if len(token) >= 3:
                terms.add(token)
    return terms


def load_board_config_document(path: Path) -> dict[str, object]:
    suffix = path.suffix.lower()
    if suffix == ".json":
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ConfigError(f"Could not parse board config {path}: {exc}") from exc
    elif suffix in BOARD_CONFIG_SUFFIXES:
        try:
            import yaml  # type: ignore[import-untyped]
        except ImportError as exc:
            raise ConfigError(
                f"PyYAML is required to load {path.name}. Run 'uv sync' from the repo root or use JSON."
            ) from exc
        try:
            data = yaml.safe_load(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, yaml.YAMLError) as exc:
            raise ConfigError(f"Could not parse board config {path}: {exc}") from exc
    else:
        raise ConfigError(f"Unsupported board config format for {path}. Use .json, .yaml, or .yml.")

    if not isinstance(data, dict):
        raise ConfigError(f"{path} must contain a single YAML or JSON object")
    return data


def make_board_config(raw: dict[str, object], source_path: Path | None) -> BoardConfig:
    forbidden_session_fields = {
        "project_path",
        "user_project_path",
        "build_command",
        "user_build_command",
        "artifact_path",
        "output_artifact_path",
        "user_output_artifact",
        "reference_firmware_path",
        "recovery_image_path",
    }
    present_forbidden = sorted(field for field in forbidden_session_fields if field in raw)
    if present_forbidden:
        raise ConfigError(
            "Board config contains project/session-scoped fields that do not belong in a durable board profile: "
            f"{', '.join(present_forbidden)}. Supply these later as runtime/session inputs instead."
        )

    required_fields = ["board_id", "display_name", "mcu_family", "probe_family", "pyocd_target"]
    missing = [field for field in required_fields if not raw.get(field)]
    if missing:
        raise ConfigError(f"Missing required board config fields: {', '.join(missing)}")

    board_id = str(raw["board_id"]).strip()
    if not re.fullmatch(r"[a-z0-9_]{1,64}", board_id):
        raise ConfigError("board_id must be 1-64 lowercase letters, numbers, or underscores")

    display_name = str(raw["display_name"]).strip()
    if not display_name:
        raise ConfigError("display_name must be a non-empty string")
    mcu_family = str(raw["mcu_family"]).strip().lower()
    probe_family = str(raw["probe_family"]).strip().lower()
    pyocd_target = str(raw["pyocd_target"]).strip()
    if "pack_name" in raw:
        source = f" in {source_path}" if source_path is not None else ""
        raise ConfigError(
            "Field 'pack_name' is unsupported"
            f"{source}; the project-local verified pack registry owns device-support metadata."
        )
    probe_type = str(raw.get("probe_type") or probe_family_label(probe_family)).strip()

    test_addr = None
    if raw.get("test_read_address") is not None:
        test_addr = parse_int(raw["test_read_address"], "test_read_address")

    default_baudrate = parse_int(raw.get("serial_baudrate", 115200), "serial_baudrate")
    uart_note = str(raw.get("uart_note", "")).strip()

    requires_recover_validation = bool(raw.get("requires_recover_validation", False))

    recover_mode = resolve_recover_mode(
        raw.get("recover_mode"),
        requires_recover_validation=requires_recover_validation,
    )

    debug_protocol = None
    if raw.get("debug_protocol") is not None:
        debug_protocol = str(raw["debug_protocol"]).strip().lower()
        if debug_protocol not in {"default", "swd", "jtag"}:
            raise ConfigError("Field 'debug_protocol' must be one of: default, swd, jtag")
    debug_connect_mode = None
    if raw.get("debug_connect_mode") is not None:
        debug_connect_mode = str(raw["debug_connect_mode"]).strip().lower()
        if debug_connect_mode not in {"attach", "halt", "pre-reset", "under-reset"}:
            raise ConfigError(
                "Field 'debug_connect_mode' must be one of: attach, halt, pre-reset, under-reset"
            )
    debug_clock_hz = None
    if raw.get("debug_clock_hz") is not None:
        debug_clock_hz = parse_int(raw["debug_clock_hz"], "debug_clock_hz")
        if debug_clock_hz <= 0:
            raise ConfigError("Field 'debug_clock_hz' must be a positive integer")

    probe_terms = set(normalize_list(raw.get("probe_hint_terms")))
    serial_terms = set(normalize_list(raw.get("serial_hint_terms")))
    default_terms = tokenize_hint_text(board_id, display_name, mcu_family, pyocd_target)
    probe_terms.update(default_terms)
    serial_terms.update(default_terms)
    probe_terms.update(probe_family_hints(probe_family))
    serial_terms.update(probe_family_hints(probe_family))
    serial_terms.add("virtual com")

    expected_uart_substring = None
    if raw.get("expected_uart_substring"):
        expected_uart_substring = str(raw["expected_uart_substring"]).strip()
    else:
        patterns = normalize_list(raw.get("reference_uart_patterns"))
        if patterns:
            expected_uart_substring = patterns[0]

    silicon_fields_present = any(
        field in raw
        for field in (
            "silicon_id_address",
            "silicon_id_expected",
            "silicon_id_mask",
            "silicon_id_width_bits",
            "silicon_id_label",
        )
    )
    silicon_id_addr = None
    silicon_id_expected = None
    silicon_id_mask = None
    silicon_id_width_bits = 32
    silicon_id_label = ""

    if silicon_fields_present:
        if raw.get("silicon_id_address") is None or raw.get("silicon_id_expected") is None:
            raise ConfigError(
                "Board config silicon identity requires both 'silicon_id_address' and "
                "'silicon_id_expected' when any silicon_id_* field is present"
            )
        silicon_id_addr = parse_int(raw["silicon_id_address"], "silicon_id_address")
        silicon_id_expected = parse_int(raw["silicon_id_expected"], "silicon_id_expected")
        silicon_id_width_bits = validate_width_bits(
            parse_int(raw.get("silicon_id_width_bits", 32), "silicon_id_width_bits"),
            "silicon_id_width_bits",
        )
        full_mask = (1 << silicon_id_width_bits) - 1
        silicon_id_mask = (
            parse_int(raw.get("silicon_id_mask", full_mask), "silicon_id_mask") & full_mask
        )
        silicon_id_expected &= full_mask
        silicon_id_label = str(raw.get("silicon_id_label") or "silicon identity").strip()

    return BoardConfig(
        board_id=board_id,
        display_name=display_name,
        mcu_family=mcu_family,
        probe_family=probe_family,
        pyocd_target=pyocd_target,
        probe_type=probe_type,
        probe_hint_terms=tuple(sorted(term.lower() for term in probe_terms if term)),
        serial_hint_terms=tuple(sorted(term.lower() for term in serial_terms if term)),
        test_addr=test_addr,
        silicon_id_addr=silicon_id_addr,
        silicon_id_expected=silicon_id_expected,
        silicon_id_mask=silicon_id_mask,
        silicon_id_width_bits=silicon_id_width_bits,
        silicon_id_label=silicon_id_label,
        default_baudrate=default_baudrate,
        uart_note=uart_note,
        requires_recover_validation=requires_recover_validation,
        recover_mode=recover_mode,
        debug_protocol=debug_protocol,
        debug_connect_mode=debug_connect_mode,
        debug_clock_hz=debug_clock_hz,
        expected_uart_substring=expected_uart_substring,
        source_path=source_path,
    )


def load_board_configs_from_paths(paths: Iterable[Path]) -> list[BoardConfig]:
    boards: list[BoardConfig] = []
    for raw_path in paths:
        path = Path(raw_path).expanduser().resolve()
        if not path.exists():
            raise ConfigError(f"Board config not found: {path}")
        document = load_board_config_document(path)
        boards.append(make_board_config(document, path))
    return boards


def iter_board_config_paths(board_config_dir: Path) -> list[Path]:
    if not board_config_dir.exists():
        raise ConfigError(f"Board config directory not found: {board_config_dir}")
    if not board_config_dir.is_dir():
        raise ConfigError(f"Board config path is not a directory: {board_config_dir}")

    paths = [
        path.resolve()
        for path in sorted(board_config_dir.iterdir())
        if path.is_file() and path.suffix.lower() in BOARD_CONFIG_SUFFIXES
    ]
    if not paths:
        raise ConfigError(f"No board config files found in: {board_config_dir}")
    return paths


def preview_board_config_paths(board_config_dir: Path) -> list[Path]:
    if not board_config_dir.exists() or not board_config_dir.is_dir():
        return []
    return [
        path.resolve()
        for path in sorted(board_config_dir.iterdir())
        if path.is_file() and path.suffix.lower() in BOARD_CONFIG_SUFFIXES
    ]


def load_default_board_configs(board_config_dir: Path) -> list[BoardConfig]:
    default_paths = [
        path
        for path in iter_board_config_paths(board_config_dir)
        if not path.stem.startswith("example_")
    ]
    if not default_paths:
        raise ConfigError(
            f"No non-example board config files found in: {board_config_dir}. "
            "Add board files or pass --board-config."
        )
    return load_board_configs_from_paths(default_paths)


def merge_board_lists(builtins: list[BoardConfig], customs: list[BoardConfig]) -> list[BoardConfig]:
    merged: list[BoardConfig] = []
    seen: set[str] = set()
    for board in builtins + customs:
        if board.board_id in seen:
            raise ConfigError(f"Duplicate board_id detected: {board.board_id}")
        seen.add(board.board_id)
        merged.append(board)
    return merged


def select_boards_by_id(
    boards: list[BoardConfig], requested_ids: Iterable[str]
) -> list[BoardConfig]:
    requested = [board_id.strip().lower() for board_id in requested_ids if board_id.strip()]
    if not requested:
        return boards

    selected = [board for board in boards if board.board_id in requested]
    missing = sorted(set(requested) - {board.board_id for board in selected})
    if missing:
        raise ConfigError(f"Requested board_id values not found: {', '.join(missing)}")
    return selected


def load_selected_board_configs(
    board_config_dir: Path,
    extra_paths: Iterable[Path] = (),
    requested_ids: Iterable[str] = (),
) -> list[BoardConfig]:
    default_boards = load_default_board_configs(board_config_dir)
    custom_boards = load_board_configs_from_paths(extra_paths)
    boards = merge_board_lists(default_boards, custom_boards)
    return select_boards_by_id(boards, requested_ids)

