                self._approved.pop(board_id, None)
            raise PlanRefusal(
                "unlock/binding-changed",
                "The target, probe, connection, safety map, erase ranges, mechanism, or plan "
                "changed before execution. Fresh disclosure and one-time approval are required.",
            )

    def invalidate_board(self, board_id: str) -> None:
        """Drop non-authorizing drafts and approved in-memory bindings on disconnect."""

        with self._guard:
            self._pending.pop(board_id, None)
            self._approved.pop(board_id, None)
        self.services.revoke_permission(board_id, "target unlock binding invalidated")

    def execute(self, board_id: str, recovery_mechanism: str) -> str:
        with self._guard:
            approved = self._approved.pop(board_id, None)
        if approved is None:
            raise PlanRefusal(
                "unlock/approval-inactive",
                "The fresh one-time approval is no longer active.",
            )
        if recovery_mechanism != approved.mechanism.mechanism_id:
            raise PlanRefusal(
                "unlock/parameter-mismatch",
                "The recovery mechanism differs from the approved typed vendor operation.",
            )
        plan_id = approved.plan_id
        fields = {
            "live_identity": asdict(approved.identity),
            "mechanism": asdict(approved.mechanism),
            "disclosure": json.loads(approved.erase_disclosure_json),
        }
        self.services.gate_manager.clear(
            board_id, "target unlock attempt started; board_validate is required"
        )
        try:
            backend = self.services.recover_target(
                self.services.handle_for(board_id), approved.mechanism.mechanism_id
            )
        except Exception:
            self._report(
                status="unlock_failed_revalidation_required",
                board_id=board_id,
                plan_id=plan_id,
                fields=fields,
            )
            raise
        self.services.mark_recover_completed(board_id)
        report = self._report(
            status="unlock_completed_revalidation_required",
            board_id=board_id,
            plan_id=plan_id,
            fields={**fields, "backend": backend},
        )
        return (
            f"Target unlock completed using {approved.mechanism.description}. The operation "
            f"performed mass erase and consumed plan {plan_id}. The validation gate remains "
            f"closed; run board_validate before any guarded read or write. Report: {report}"
        )


def build_unlock_handlers(
    coordinator: UnlockCoordinator,
) -> dict[str, Callable[..., str]]:
    def target_unlock_plan(
        board_id: str | None = None,
        hypothesis: str | None = None,
        strategy: str | None = None,

    return connection

def maybe_connection(self, board_id: str) -> ManagedConnection | None:
    normalized = self._normalize_board_id(board_id)
    with self._guard:
        return self._connections.get(normalized)

def handle_for(self, board_id: str) -> TargetSessionHandle:
    return self.connection_for(board_id).handle

def runtime_for(self, board_id: str) -> SessionRecord:
    return self.connection_for(board_id).runtime_session

def clear(self, board_id: str) -> ManagedConnection | None:
    """Remove only the named assignment, leaving other boards untouched."""

    normalized = self._normalize_board_id(board_id)
    with self._guard:
        connection = self._connections.pop(normalized, None)
        if connection is not None:
            self._boards_by_connection.pop(connection.connection_id, None)
        return connection

def clear_if_current(
    self,
    board_id: str,
    expected: ManagedConnection,
) -> ManagedConnection | None:
    """Remove the assignment only when it is still the exact captured object."""

    normalized = self._normalize_board_id(board_id)
    with self._guard:
        current = self._connections.get(normalized)
        if current is not expected:
            return None
        connection = self._connections.pop(normalized)
        self._boards_by_connection.pop(connection.connection_id, None)
        return connection

def assigned_board_ids(self) -> tuple[str, ...]:
    with self._guard:
        return tuple(sorted(self._connections))

"""Minimal MCP server exposing pyOCD debug control to an LLM client.

Design notes
------------
* Debug sessions are *stateful* (halt state, breakpoints, and live target
  connections persist across calls), so each logical board owns one explicit
  connection until it is disconnected.
* pyOCD's target access is blocking and **not thread-safe**. Each live session
  therefore has one serialized worker process.
* A missed provider deadline terminates that worker without poisoning another
  board or the MCP transport.
"""

